try {
    // 1. Читаем входящие параметры от Агента (Dify пришлет их в body вебхука)
    const payload = $input.item.json.body || {};

    // Достаем email сотрудника
    const employeeEmail = payload.employee_email || "andcoestate@gmail.com";

    let timeMin, timeMax, displayDate, queryMode;

    // 🚨 ВАЖНО: Фиксируем часовой пояс для Днепра/Киева (UTC+3)
    // Мы больше не используем .toISOString(), так как он ломает часовые пояса
    const TZ = "+03:00";

    // СЦЕНАРИЙ А: Агент прислал диапазон дат (например, "на следующей неделе")
    if (payload.start_date && payload.end_date) {
        queryMode = "range";

        // Ручная сборка строки времени с нашим часовым поясом
        timeMin = `${payload.start_date}T00:00:00${TZ}`;
        timeMax = `${payload.end_date}T23:59:59${TZ}`;

        displayDate = `период с ${payload.start_date} по ${payload.end_date}`;
    } 
    // СЦЕНАРИЙ Б: Агент прислал конкретную дату (например, "во вторник")
    else if (payload.target_date) {
        queryMode = "specific_date";

        // Формируем жесткие границы дня для Google Календаря
        timeMin = `${payload.target_date}T00:00:00${TZ}`;
        timeMax = `${payload.target_date}T23:59:59${TZ}`;

        // Оставляем твой красивый вывод для промпта ИИ
        let target = new Date(payload.target_date);
        displayDate = target.toLocaleDateString('ru-RU', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    } 
    // СЦЕНАРИЙ В: Безопасный режим по умолчанию (Fall-back на "Завтра")
    else {
        queryMode = "fallback_tomorrow";
        let tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);

        // Достаем год, месяц и день с добавлением нулей спереди (04 вместо 4)
        let yyyy = tomorrow.getFullYear();
        let mm = String(tomorrow.getMonth() + 1).padStart(2, '0');
        let dd = String(tomorrow.getDate()).padStart(2, '0');

        // Формируем границы завтрашнего дня
        timeMin = `${yyyy}-${mm}-${dd}T00:00:00${TZ}`;
        timeMax = `${yyyy}-${mm}-${dd}T23:59:59${TZ}`;

        displayDate = tomorrow.toLocaleDateString('ru-RU', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }) + " (по умолчанию)";
    }

    // 2. Отдаем стандартизированные данные для Google Календаря
    // Обернул в массив [{}], так как новые версии n8n требуют массив на выходе из узла Code
    return [{
        json: {
            timeMin: timeMin,
            timeMax: timeMax,
            targetDate: displayDate,
            employee_email: employeeEmail,
            _execution_mode: queryMode
        }
    }];

} catch (error) {
    throw new Error("[СБОЙ ПАРСИНГА ДАТЫ] Убедитесь, что Агент передает формат YYYY-MM-DD. Детали: " + error.message);
}

try {
    const items = $input.all();
    const timeNode = $("Set Time Range").first().json || {};
    const targetDate = timeNode.targetDate || "выбранный период";

    // Если Гугл не вернул событий вообще
    if (!items || items.length === 0 || (items.length === 1 && !items[0].json.id)) {
         return [{ json: { status: "success", calendar_data: `На ${targetDate} календарь полностью свободен. Предложи клиенту слоты с 10:00 до 18:00.` } }];
    }

    let scheduleMap = {};
    let hasBusyEvents = false;

    items.forEach(item => {
        const event = item.json;

        // 🚨 ГЛАВНАЯ ЗАЩИТА: Пропускаем события, которые не занимают время (Free/Transparent)
        if (event.transparency === 'transparent') return;
        // Пропускаем отмененные события
        if (event.status === 'cancelled') return;
        if (!event || !event.start) return;

        hasBusyEvents = true;

        const isAllDay = !!event.start.date;
        let start = new Date(isAllDay ? event.start.date : event.start.dateTime);
        let end = new Date(isAllDay ? event.end.date : event.end.dateTime);

        // 🚨 ЖЕСТКИЙ ЧАСОВОЙ ПОЯС ПРИ ВЫВОДЕ В ТЕКСТ
        let timeOpts = { timeZone: 'Europe/Kyiv', hour: '2-digit', minute: '2-digit' };
        let dateOpts = { timeZone: 'Europe/Kyiv', day: '2-digit', month: '2-digit', year: 'numeric' };

        let dateKey = start.toLocaleDateString('ru-RU', dateOpts);
        if (!scheduleMap[dateKey]) scheduleMap[dateKey] = [];

        if (isAllDay) {
            scheduleMap[dateKey].push("[ВЕСЬ ДЕНЬ ЗАНЯТ]");
        } else {
            let startTime = start.toLocaleTimeString('ru-RU', timeOpts);
            let endTime = end.toLocaleTimeString('ru-RU', timeOpts);
            scheduleMap[dateKey].push(`${startTime} - ${endTime}`);
        }
    });

    // Если все события были "прозрачными" (например, просто напоминания)
    if (!hasBusyEvents) {
         return [{ json: { status: "success", calendar_data: `На ${targetDate} реальных встреч нет (календарь свободен). Предложи клиенту слоты с 10:00 до 18:00.` } }];
    }

    let aiPrompt = `ИНСТРУКЦИЯ ПО КАЛЕНДАРЮ на ${targetDate}:\nУЖЕ ЗАНЯТОЕ ВРЕМЯ:\n`;
    for (let date in scheduleMap) {
        aiPrompt += `📅 ${date}: ${scheduleMap[date].join(', ')}\n`;
    }
    aiPrompt += `\nЗАДАЧА: Сверься с занятым временем. Если клиент уже предложил конкретное время, и оно СВОБОДНО — соглашайся. Если занято или не предложено — предложи 2 свободных слота по 30 минут (строго между 10:00 и 18:00).`;

    return [{ json: { status: "success", calendar_data: aiPrompt } }];

} catch (error) {
    return [{ json: { status: "error", calendar_data: `Сбой парсера календаря: ${error.message}. Переведи диалог на менеджера.` } }];
}
